SINA_SMART["anat1-forearm"] = {"lecture":"anat1-forearm","title":"Topographic anatomy of the forearm","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-forearm:e0","text":"Forearm: anterior, lateral, posterior compartments.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-forearm:e1","text":"Layer 1: PT, FCR, PL, FCU (medial epicondyle).","topic":"Anterior compartment","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-forearm:e2","text":"Layer 2: FDS → middle phalanges; Layer 3: FPL, FDP → distal phalanges.","topic":"Anterior compartment","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-forearm:e3","text":"Layer 4: supinator (radial n.), pronator quadratus (median n.).","topic":"Anterior compartment","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-forearm:e4","text":"Median n. supplies all anterior muscles except FCU and medial half of FDP (ulnar n.).","topic":"Anterior compartment","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-forearm:e5","text":"Radial pulse between FCR and brachioradialis tendons.","topic":"Anterior compartment","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-forearm:e6","text":"Lateral: brachioradialis, ECRL (2nd MC), ECRB (3rd MC).","topic":"Lateral and posterior compartments","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-forearm:e7","text":"Posterior (deep radial n.): extensor digitorum, EDM, ECU, anconeus; APL, EPB, EPL, extensor indicis.","topic":"Lateral and posterior compartments","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"h6t2nb":"a","13gszqm":"a","17a1rg0":"a","1p84792":"a","74lyoa":"a","14b9he":"a","1lj4c0b":"a","x5uvfi":"a","1t8y8ac":"a","c8zpna":"a","1rj1r1w":"a","jk4hdi":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-forearm:e0":{"s":0,"u":["Forearm: anterior, lateral, posterior compartments.","A section through the middle third of the forearm shows three muscular compartments: anterior (flexors and pronators, with the median and ulnar nerves and the radial and ulnar arteries), lateral and posterior (extensors, radial nerve)."],"dp":[{"h":"Clinical","t":"Anterior interosseous nerve (median) injury: cannot make the 'OK' sign (FPL and lateral FDP weak); no sensory loss."}]},"anat1-forearm:e1":{"s":1,"u":["Layer 1: PT, FCR, PL, FCU (medial epicondyle).","Layer 1 (epitrochlear, from the medial epicondyle; lateral to medial): pronator teres (→ lateral radius; pronation; median n.), flexor carpi radialis (→ base of 2nd metacarpal; wrist flexion), palmaris longus (→ palmar aponeurosis), flexor carpi ulnaris (→ pisiform; ulnar n. ).","Ulnar nerve : from the epicondylo-olecranon groove, runs under flexor carpi ulnaris; supplies FCU and the medial half of FDP."],"dp":[]},"anat1-forearm:e2":{"s":1,"u":["Layer 2: FDS → middle phalanges; Layer 3: FPL, FDP → distal phalanges.","Layer 2 : flexor digitorum superficialis (medial epicondyle, ulna, radius; its arch covers the median nerve) → sides of the middle phalanges of fingers 2-5; flexes the middle phalanx.","Layer 3 : flexor pollicis longus (anterior radius → distal phalanx of the thumb) and flexor digitorum profundus (anterior ulna → distal phalanges of fingers 2-5; median n. for fingers 2-3, ulnar n. for fingers 4-5 )."],"dp":[{"h":"How to test FDS and FDP separately","t":"Because FDS flexes the middle phalanx and FDP the distal phalanx, each can be tested alone. Holding the other fingers straight blocks FDP (it shares one muscle belly), so the patient flexes the proximal interphalangeal joint with FDS alone; stabilising the middle phalanx and asking for flexion of the fingertip tests FDP. This helps localise tendon cuts and nerve injuries. Source: the lecture's anterior compartment layers."},{"h":"Note","t":"FDS → middle phalanges (PIP flexion); FDP → distal phalanges (DIP flexion); FPL → distal phalanx of the thumb. FDS tendons split to let FDP pass."}]},"anat1-forearm:e3":{"s":1,"u":["Layer 4: supinator (radial n.), pronator quadratus (median n.).","Layer 4 : supinator (lateral epicondyle → proximal radius; supination; deep radial n.) and pronator quadratus (distal radius ↔ ulna; median n.)."],"dp":[{"h":"Note","t":"Pronators: pronator teres and pronator quadratus (median). Supinators: supinator (radial) and biceps (musculocutaneous). Brachioradialis flexes the elbow in mid-prone position."}]},"anat1-forearm:e4":{"s":1,"u":["Median n. supplies all anterior muscles except FCU and medial half of FDP (ulnar n.).","Median nerve : passes under the arch of FDS and supplies all anterior muscles except flexor carpi ulnaris and the medial half of FDP .","Ulnar nerve : from the epicondylo-olecranon groove, runs under flexor carpi ulnaris; supplies FCU and the medial half of FDP."],"dp":[{"h":"Note","t":"Median nerve supplies all anterior forearm muscles except FCU and the medial half of FDP (ulnar). The radial nerve (deep branch) supplies all posterior and lateral muscles."}]},"anat1-forearm:e5":{"s":1,"u":["Radial pulse between FCR and brachioradialis tendons.","The radial artery runs under brachioradialis, then superficially in the pulse groove between the flexor carpi radialis (medially) and brachioradialis (laterally) tendons: where the radial pulse is taken."],"dp":[]},"anat1-forearm:e6":{"s":2,"u":["Lateral: brachioradialis, ECRL (2nd MC), ECRB (3rd MC).","Lateral (radial nerve): brachioradialis (lateral supracondylar humerus → radial styloid; elbow flexion), extensor carpi radialis longus (→ base of 2nd metacarpal) and brevis (→ base of 3rd metacarpal): wrist extension."],"dp":[{"h":"Note","t":"Wrist extensors insert on metacarpal bases: ECRL → 2nd , ECRB → 3rd , ECU → 5th ; FCR → 2nd; FCU → pisiform."},{"h":"Clinical","t":"Posterior interosseous nerve (deep radial) injury: finger and thumb drop but no wrist drop (ECRL and brachioradialis are supplied above) and no sensory loss ."}]},"anat1-forearm:e7":{"s":2,"u":["Posterior (deep radial n.): extensor digitorum, EDM, ECU, anconeus; APL, EPB, EPL, extensor indicis.","Posterior (deep branch of radial nerve): superficial layer: anconeus (elbow extension), extensor digitorum (four tendons; central slip → middle phalanx, lateral slips → distal phalanx), extensor digiti minimi , extensor carpi ulnaris (→ base of 5th metacarpal); deep layer: abductor pollicis longus (→ base of 1st metacarpal), extensor pollicis brevis (→ proximal phalanx of thumb), extensor pollicis longus (→ distal phalanx of thumb), extensor indicis ."],"dp":[]}},"meta":{"h6t2nb":{"a":"recall","vg":"anat1-forearm:e0/recall/1"},"13gszqm":{"a":"recall","vg":"anat1-forearm:e2/recall/1"},"17a1rg0":{"a":"recall","vg":"anat1-forearm:e1/recall/1"},"1p84792":{"a":"recall","vg":"anat1-forearm:e2/recall/2"},"74lyoa":{"a":"recall","vg":"anat1-forearm:e4/recall/1"},"14b9he":{"a":"recall","vg":"anat1-forearm:e2/recall/3"},"1lj4c0b":{"a":"recall","vg":"anat1-forearm:e4/recall/2"},"x5uvfi":{"a":"relationship","vg":"anat1-forearm:e5/relationship/1"},"1t8y8ac":{"a":"recall","vg":"anat1-forearm:e3/recall/1"},"c8zpna":{"a":"recall","vg":"anat1-forearm:e5/recall/1"},"1rj1r1w":{"a":"recall","vg":"anat1-forearm:e7/recall/1"},"jk4hdi":{"a":"recall","vg":"anat1-forearm:e0/recall/2"}},"explRev":"c0e6cc275b55"};
